import{_ as l,o as e,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-11-20","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-11-20","date":"2024-11-20T00:00:00.000Z","updated":"2024-11-20T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","版本控制","向量数据库"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-11-20.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-11-20.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-11-20.md"};function r(n,i,s,h,g,p){return e(),t("div",null,[...i[0]||(i[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph 分布式存储系统中的应用演示与技术讨论</p><p><strong>会议时间</strong>: 2024-11-20</p><p><strong>参会人员</strong>:</p><ul><li>Jin：会议主持人，Ceph 研发人员</li><li>Igor：Ceph 研发人员，负责版本控制系统的改进</li><li>其他参会人员：包括 Ceph 团队成员及外部专家</li></ul><h3 id="会议内容总结" tabindex="-1">会议内容总结 <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结&quot;">​</a></h3><h4 id="_1-jin-的应用演示" tabindex="-1">1. Jin 的应用演示 <a class="header-anchor" href="#_1-jin-的应用演示" aria-label="Permalink to &quot;1. Jin 的应用演示&quot;">​</a></h4><ul><li><strong>背景</strong>: 演示了如何将 Ceph 对象存储与向量数据库结合，用于对象和图像的向量化处理。</li><li><strong>技术细节</strong>: <ul><li>使用 Ceph 的 RGW (RADOS Gateway) 服务，结合 MiniKube 集群进行配置。</li><li>创建了两个应用程序，一个用于处理文本，另一个用于处理图像。</li><li>通过 Kubernetes 配置了 Knative 和 Kafka 通道，用于接收对象创建和删除的通知。</li><li>展示了如何将对象上传到 Ceph 的 RGW，并自动生成向量，存储在 Milvus 向量数据库中。</li><li>通过 Python 程序进行相似性搜索，搜索结果基于向量化的文本或图像。</li></ul></li><li><strong>讨论点</strong>: <ul><li>是否将搜索功能直接集成到 RGW 中，还是保持独立。</li><li>计划在未来的会议上展示该功能，收集更多来自数据科学和 AI 领域的反馈。</li></ul></li></ul><h4 id="_2-igor-的版本控制改进讨论" tabindex="-1">2. Igor 的版本控制改进讨论 <a class="header-anchor" href="#_2-igor-的版本控制改进讨论" aria-label="Permalink to &quot;2. Igor 的版本控制改进讨论&quot;">​</a></h4><ul><li><strong>背景</strong>: Ceph 的 RGW 当前的版本控制系统依赖于对象键和版本对象的 Epoch（64位整数值），在多站点部署中可能会导致对象历史记录不一致。</li><li><strong>问题描述</strong>: <ul><li>在多站点环境中，由于并发写入，可能会导致对象的历史记录在不同站点之间不一致。</li><li>当前的解决方案是通过随机生成的版本 ID 进行字典序比较，随机选择一个版本作为当前版本，这可能导致灾难恢复时用户看到不同的历史记录。</li></ul></li><li><strong>解决方案</strong>: <ul><li>使用时间戳代替 Epoch，以确保在多站点环境中，对象的历史记录可以按时间顺序排列。</li><li>在时间戳相同的情况下，仍然需要一个机制来解决冲突，可能通过配置指定主站点优先或其他策略。</li></ul></li><li><strong>讨论点</strong>: <ul><li>时间戳的精度。</li><li>升级兼容性。</li><li>冲突解决机制。</li></ul></li><li><strong>结论</strong>: <ul><li>初步决定使用时间戳代替 Epoch，并继续使用字典序比较作为冲突解决的默认方式。未来可以进一步讨论是否需要引入更复杂的冲突解决机制。</li></ul></li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ol><li>Jin：继续完善向量数据库与 Ceph 的集成，计划在未来的会议上展示该功能，收集更多用户反馈。</li><li>Igor：开始实现基于时间戳的版本控制改进，确保高分辨率时间戳的使用，并处理升级时的兼容性问题。</li></ol><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ol><li>Jin：准备在未来的会议上展示向量数据库与 Ceph 的集成功能，收集用户反馈。</li><li>Igor：开始实现基于时间戳的版本控制系统改进，确保高分辨率时间戳的使用，并处理升级时的兼容性问题。</li></ol><p><strong>会议结束时间</strong>: 未知</p>',15)])])}const c=l(o,[["render",r]]);export{u as __pageData,c as default};
